ui.css:
.hud-panel { padding: 8px 30px 9px; border: 4px solid #17131c; border-radius: 70px 70px 16px 16px / 56px 56px 16px 16px; background: radial-gradient(ellipse at 50% 30%, rgba(255,230,170,.28), transparent 60%), radial-gradient(ellipse at 50% 35%, #4a63c8 0%, #26357e 55%, #141b48 100%); box-shadow: 0 0 0 2px #d9ad4e, 0 0 0 6px #17131c, 0 8px 18px rgba(0,0,0,.55), inset 0 0 18px rgba(0,0,30,.6); font-family: 'Cinzel Decorative', 'Cinzel', serif; font-weight: 900; color: #ffdf7e; }
.hp-bar { position: relative; width: 250px; height: 26px; border: 3px solid #17131c; border-radius: 14px; overflow: hidden; background: linear-gradient(180deg, #2a0c16, #4a1626 50%, #22080f); box-shadow: 0 0 0 2px #d9ad4e, 0 0 0 5px #17131c, 0 5px 12px rgba(0,0,0,.55), inset 0 3px 5px rgba(0,0,0,.6); }
.hp-fill { height: 100%; background: repeating-linear-gradient(90deg, transparent 0 46px, #17131c 46px 49px), linear-gradient(180deg, #ffc0b4 0%, #ec3c52 44%, #9a1630 100%); box-shadow: 0 0 12px rgba(255,90,110,.6); }
.hp-fill::after { content: ''; position: absolute; left: 7px; right: 7px; top: 3px; height: 5px; border-radius: 3px; background: rgba(255,255,255,.5); }
